function activeQuestionData(){
 const key=threadKey()+'::'+chess.fen().split(' ').slice(0,4).join(' ');
 if(!questionSessions.has(key))questionSessions.set(key,makeQuestionState());
 const state=questionSessions.get(key),deck=questionDeck(chess,lesson,engineResult?.fen===chess.fen()?engineResult:null);
 return {key,state,deck,...currentQuestion(state,deck)};
}
