function renderFreeCoachPanel(){
 const q=activeQuestionData(),report=coachReport(chess,engineResult),log=thread(),latest=[...log].reverse().find(x=>x.role==='assistant');
 return `<aside class="ask-coach" aria-label="Free Coach"><div class="section-heading"><div><p class="eyebrow">FREE COACH</p><h2>Understand. Answer. Keep learning.</h2></div><span class="coach-dot"></span></div><p class="coach-connection">Stockfish + programmed explanations · no API credits</p><section id="coachQuestionContainer" class="coach-question-container" tabindex="-1" aria-label="Current Coach question"><div class="question-heading"><span class="mini-label">QUESTION ${q.number} OF ${q.deck.length} · ROUND ${q.round}</span><span class="mini-label">${side(chess.turn())} to move</span></div><h3 id="activeCoachQuestion">${esc(q.item.question)}</h3><label for="coachAnswer" class="mini-label">YOUR ANSWER</label><textarea id="coachAnswer" placeholder="Explain your thinking in your own words…" maxlength="2500">${esc(q.state.draft)}</textarea><button class="primary" data-action="coachSubmit">Submit answer & next →</button><div class="question-navigation" role="group" aria-label="Coach question navigation"><button class="secondary" data-action="coachBack" ${q.state.cursor===0?'disabled':''}>← Back</button><button class="secondary" data-action="coachNext">Next →</button><button class="secondary" data-action="coachRestart">Restart</button></div><p class="notice">Your answer is saved, then the next question appears. Compare your reasoning with the explanation in history; free-text answers are not automatically graded.</p></section><details class="coach-history"><summary>Previous Coach questions & explanations (${q.state.history.length})</summary><div class="question-history-list">${[...q.state.history].reverse().map(x=>`<article><h4>${esc(x.question)}</h4><p><b>Your answer:</b> ${esc(x.answer)}</p><div class="chat-text"><b>Explanation:</b> ${esc(x.explanation)}</div></article>`).join('')||'<p>No answers saved for this position yet.</p>'}</div></details><section class="free-engine-coaching" aria-label="Free engine explanations"><h3>What Stockfish and the board show</h3><p>${esc(report.summary)}</p>${report.classification?`<div class="move-grade grade-${esc(report.classification.code||'unrated')}"><span>MOVE QUALITY · SHORT SEARCH</span><strong>${esc(report.classification.label)}</strong>${report.classification.loss!==null?`<small>Estimated change: ${Math.max(0,report.classification.loss).toFixed(2)} pawn units for the mover</small>`:''}</div>`:''}${report.alerts.map(a=>`<article class="coach-finding"><h4>${esc(a.title)}</h4><p>${esc(a.text)}</p></article>`).join('')}<div class="button-row"><button class="secondary" data-action="reviewMove" ${!chess.history().length||playing?'disabled':''}>Review my last move</button><button class="secondary" data-action="analyze" ${playing?'disabled':''}>Analyze candidates</button></div></section><section class="coach-ask-form"><h3>Ask the free Coach</h3><div class="question-chips">${['Why this move?','What is White’s plan?','What is Black’s plan?','What did I miss?'].map(text=>`<button data-coach-prompt="${esc(text)}">${text}</button>`).join('')}</div><label for="coachQuestion" class="mini-label">YOUR CHESS QUESTION</label><textarea id="coachQuestion" placeholder="Ask about the plan, threats, or your last move…" maxlength="2500">${esc(coachDraft)}</textarea><div class="button-row"><button class="primary" data-action="askGuide" ${coachBusy?'disabled':''}>${coachBusy?'Analyzing locally…':'Ask free Coach'}</button><button class="secondary" data-action="deepCoach" ${coachBusy?'disabled':''}>Explain the idea</button></div>${coachError?`<div class="feedback error" role="status">${esc(coachError)}</div>`:''}${latest?`<article class="current-coach-reply" aria-label="Latest Coach explanation"><span class="mini-label">LATEST EXPLANATION · ${esc(latest.move||'')}</span><div class="chat-text">${esc(latest.text)}</div></article>`:''}<details class="coach-history"><summary>Previous conversations (${log.filter(x=>x.role==='user').length})</summary><div class="chat-log" role="log" aria-label="Coach conversation">${log.map(x=>`<div class="chat-message ${x.role}"><span class="chat-role">${x.role==='user'?'YOU':x.source==='ai'?'EARLIER AI ANSWER':'FREE COACH'} · ${esc(x.move||'')}</span><div class="chat-text">${esc(x.text)}</div></div>`).join('')||'<p>No conversation history yet.</p>'}</div></details></section><section class="chatgpt-handoff"><h3>Want a longer conversation?</h3><p>Ask ChatGPT shows your question and complete chess position first. Copy the prompt, then choose when to open ChatGPT. You can save a direct link to your chess project or an existing conversation.</p><div class="button-row"><button class="primary" data-action="askChatGPT">Ask ChatGPT ↗</button><button class="secondary" data-action="copyContext">Copy coaching prompt</button></div><p class="notice">For a fuller prompt, use Review my last move first. No moves are sent automatically, and ChatGPT is not embedded here.</p></section><div class="analysis-options"><label for="analysisTime">Analysis time</label><select id="analysisTime"><option value="1800" ${analysisTime===1800?'selected':''}>Quick · 2 sec</option><option value="5000" ${analysisTime===5000?'selected':''}>Deeper · 5 sec</option><option value="10000" ${analysisTime===10000?'selected':''}>Study · 10 sec</option></select><button class="secondary" data-action="glossary">Chess terms explained</button></div></aside>`;
}
function navigateCoachQuestion(action){
 pausePlayback();const q=activeQuestionData(),draft=$('#coachAnswer')?.value??q.state.draft;
 if(action==='coachSubmit'){if(!submitQuestion(q.state,q.deck,draft)){toast('Write an answer, or use Next to skip.');$('#coachAnswer')?.focus();return}}
 if(action==='coachNext'){if(draft.trim())submitQuestion(q.state,q.deck,draft);else nextQuestion(q.state)}
 if(action==='coachBack')previousQuestion(q.state);
 if(action==='coachRestart')restartQuestions(q.state);
 saveQuestionSessions();renderLearningExtras();focusCurrentCoachQuestion();
}
function focusCurrentCoachQuestion(){
 const target=$('#coachQuestionContainer');if(!target)return;
 target.scrollTop=0;const panel=target.closest('.ask-coach');if(panel)panel.scrollTop=0;
 try{target.focus({preventScroll:true})}catch{target.focus()}
 target.scrollIntoView({block:'start',behavior:'auto'});
}
function coachingPrompt(question){return buildChatGPTPrompt(learningContext(),question??$('#coachQuestion')?.value??coachDraft)}
function savedChessChatUrl(){try{return localStorage.getItem('knight-school-chatgpt-destination')||''}catch{return ''}}
function validChessChatUrl(value){
 try{const url=new URL(value);return url.protocol==='https:' && ['chatgpt.com','chat.openai.com'].includes(url.hostname)&&!url.port&&!url.username&&!url.password&&![...url.searchParams.keys()].some(k=>/^(q|prompt|message|text)$/i.test(k)) ? url.href : ''}catch{return ''}
}
function showChatGPTHandoff(){
 pausePlayback();
 const question=($('#coachQuestion')?.value||coachDraft||latestCoachQuestions.get(threadKey())||[...thread()].reverse().find(x=>x.role==='user')?.text||'Explain this position, my last move, the opponent’s threats, and a useful plan.').trim();
 const initialPrompt=coachingPrompt(question);
 modal(`<h2>Ask ChatGPT about this position</h2><p>Review your question, copy the complete prompt, and <b>then</b> choose when to open ChatGPT. Nothing opens automatically.</p><label for="chatgptQuestion" class="mini-label">YOUR QUESTION — INCLUDED IN THE PROMPT</label><textarea id="chatgptQuestion" class="prompt-fallback" style="min-height:90px" maxlength="2500">${esc(question)}</textarea><label for="chatgptPrompt" class="mini-label">COMPLETE COACHING PROMPT</label><textarea id="chatgptPrompt" class="prompt-fallback" readonly>${esc(initialPrompt)}</textarea><p id="copyPromptStatus" role="status">Step 1: Copy your prompt. Step 2: Open your chosen ChatGPT conversation.</p><div class="button-row"><button class="primary" id="copyPromptNow">Copy complete prompt</button><button class="secondary" id="selectPrompt">Select all</button><button class="secondary" id="manualCopyDone" hidden>I copied it manually</button></div><label for="chessChatDestination" class="mini-label">YOUR CHESS PROJECT OR CONVERSATION LINK (OPTIONAL)</label><input id="chessChatDestination" type="url" inputmode="url" placeholder="Paste your ChatGPT project link here" value="${esc(savedChessChatUrl())}" style="width:100%;max-width:100%;font-size:16px;padding:11px"><button class="secondary" id="saveChessChatDestination">Save destination</button><p class="notice">To open your existing chess project: open it in ChatGPT, copy its browser URL, and paste it here once. Knight School saves the link on this device. ChatGPT may still ask you to select a conversation inside that project.</p><div class="button-row"><button class="secondary" id="openChatGPTNow">Open ChatGPT (after copying) ↗</button></div><p class="notice">The prompt is not automatically pasted or sent. Paste it into ChatGPT and press Send. No API credits are used.</p>`);
 const promptField=$('#chatgptPrompt'),questionField=$('#chatgptQuestion'),status=$('#copyPromptStatus'),dest=$('#chessChatDestination'),open=$('#openChatGPTNow');
 let copied=false;
 open.disabled=true;
 questionField.addEventListener('input',()=>{coachDraft=questionField.value;promptField.value=coachingPrompt(questionField.value);copied=false;open.disabled=true;$('#manualCopyDone').hidden=true;status.textContent='Question updated. Copy the new prompt before opening ChatGPT.'});
 dest.addEventListener('change',()=>{const value=dest.value.trim();if(!value){try{localStorage.removeItem('knight-school-chatgpt-destination')}catch{}return}const checked=validChessChatUrl(value);if(!checked){status.textContent='That destination is not a secure ChatGPT link. Paste a URL beginning with https://chatgpt.com/';return}dest.value=checked;try{localStorage.setItem('knight-school-chatgpt-destination',checked)}catch{}status.textContent='Chess ChatGPT destination saved on this device.'});
 $('#saveChessChatDestination').onclick=()=>dest.dispatchEvent(new Event('change',{bubbles:true}));
 $('#selectPrompt').onclick=()=>{promptField.focus();promptField.select();promptField.setSelectionRange(0,promptField.value.length);status.textContent='Prompt selected. Use Copy, then open ChatGPT.'};
 $('#copyPromptNow').onclick=async()=>{
   const value=promptField.value;
   try{if(!navigator.clipboard?.writeText)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(value);if(promptField.value!==value){copied=false;open.disabled=true;status.textContent='Question changed. Copy the updated prompt.';return}copied=true;open.disabled=false;status.textContent='Complete prompt copied, including your question! Now you can open ChatGPT.'}
   catch{copied=false;open.disabled=true;promptField.focus();promptField.select();status.textContent='Safari blocked automatic copying. The prompt is selected: use Copy from the text selection. Confirm with “I copied it manually” after copying.';$('#manualCopyDone').hidden=false}
 };
 $('#manualCopyDone').onclick=()=>{copied=true;open.disabled=false;status.textContent='Manual copy confirmed. Open ChatGPT, paste the prompt, then send it.'};
 open.onclick=()=>{if(!copied)return;const value=dest.value.trim(),target=value?validChessChatUrl(value):'https://chatgpt.com/';if(!target){status.textContent='Invalid ChatGPT project link. Remove it or paste a proper ChatGPT URL.';return}if(value){try{localStorage.setItem('knight-school-chatgpt-destination',target)}catch{}}window.open(target,'_blank','noopener,noreferrer');status.textContent='ChatGPT opened. Paste your copied prompt there and send it.'};
}
function openChatGPTHandoff(){showChatGPTHandoff()}
function copyCoachingPrompt(){showChatGPTHandoff()}
document.addEventListener('input',e=>{if(e.target.id==='coachAnswer'){const q=activeQuestionData();q.state.draft=e.target.value;saveQuestionSessions()}});

try{const theme=localStorage.getItem('knight-school-board-theme');document.documentElement.dataset.boardTheme=['walnut','tournament','slate'].includes(theme)?theme:'walnut'}catch{document.documentElement.dataset.boardTheme='walnut'}
document.addEventListener('change',e=>{if(e.target.id==='boardTheme'){document.documentElement.dataset.boardTheme=e.target.value;try{localStorage.setItem('knight-school-board-theme',e.target.value)}catch{}}});

function persistTraining(){try{localStorage.setItem(trainingKey,JSON.stringify(training));return true}catch{toast('Training data could not be saved. Download a backup before closing this tab.');return false}}
function sideName(s){return s==='both'?'Both sides':side(s)}
function studyName(id){return [...families,...teachBranchLessons,...openings,...strategies,...endgames,...masters].find(x=>x.id===id)?.name||id}
function dateLabel(value){return new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}
function reviewQueueSummary(){const due=dueReviews(training).length;return `<div class="review-queue-banner"><div><span class="mini-label">YOUR NEXT REVIEW</span><h3>${due?due+' opening '+(due===1?'review is':'reviews are')+' ready':'Build a repertoire that stays with you.'}</h3><p>Spaced practice, a mistake notebook, and complete progress backups.</p></div><button class="secondary" data-training-progress>Training progress →</button></div>`}
function finishRecall(){
 const key=reviewKey(lesson.id,drillSide),previous=training.reviews[key],now=Date.now();pendingRecallResult={lessonId:lesson.id,side:drillSide,previous,now};
 const grade=drillErrors?'again':drillHints?'hard':'good';training.reviews[key]=scheduleReview(previous,{lessonId:lesson.id,side:drillSide,grade,now});
 training.sessions.push({id:globalThis.crypto?.randomUUID?.()||String(now)+'-'+Math.random().toString(36).slice(2),at:new Date(now).toISOString(),lessonId:lesson.id,side:drillSide,errors:drillErrors,hints:drillHints});persistTraining();
}
function recallResultMarkup(){if(!pendingRecallResult||pendingRecallResult.lessonId!==lesson?.id||drill)return '';const r=training.reviews[reviewKey(pendingRecallResult.lessonId,pendingRecallResult.side)];return `<section class="recall-result" aria-label="Opening recall result"><span class="mini-label">SPACED PRACTICE · ${sideName(r.side)}</span><h3>Next review: ${dateLabel(r.due)}</h3><p>${drillErrors} missed moves · ${drillHints} hints. Adjust how well you remembered this line:</p><div class="recall-ratings">${[['again','Again · 10 min'],['hard','Hard'],['good','Good'],['easy','Easy']].map(([g,t])=>`<button class="secondary ${r.grade===g?'active':''}" data-recall-grade="${g}" aria-pressed="${r.grade===g}">${t}</button>`).join('')}</div></section>`}
function saveAnalyzedMistake(){const m=createMistake(chess,engineResult,lesson?.id||page);if(rememberMistake(training,m))persistTraining()}
function mistakeStudyMarkup(){const m=activeMistakeId&&training.mistakes.find(x=>x.id===activeMistakeId);if(!m||page!=='practice')return '';return `<section class="mistake-study" aria-label="Mistake recall"><span class="mini-label">YOUR MISTAKE NOTEBOOK</span><h3>Find a better move than ${esc(m.played)}.</h3><p><b>1. Your move:</b> ${esc(m.played)}. The board shows the position before it.</p><p><b>2. Try again:</b> ${side(m.mover)} to move. Look for checks, captures and threats. The answer stays hidden until you reveal it.</p><details><summary>Reveal candidate and explanation</summary><p><b>3. A better candidate:</b> ${esc(m.bestMove)} · ${esc(m.line.slice(0,8).join(' '))}</p><p><b>4. What the move allowed and why the candidate helps:</b></p><div class="chat-text">${esc(m.explanation)}</div><p>Short engine searches can change. This is a candidate to study, not the only legal move.</p></details><button class="secondary" data-training-progress>Back to training record</button></section>`}
function checkNotebookMove(move){const m=activeMistakeId&&training.mistakes.find(x=>x.id===activeMistakeId);if(!m||move.before!==m.fenBefore)return;if(move.from+move.to+(move.promotion||'')===m.bestUci){m.reviewCount=(m.reviewCount||0)+1;m.reviewedAt=new Date().toISOString();persistTraining();feedback='You found the earlier Stockfish candidate. Study the reply and compare the explanation.'}else feedback='That is legal. Compare it with the earlier candidate in your mistake notebook.'}
function exportFullBackup(){try{saveChats();saveQuestionSessions();const backup=makeBackup(localStorage);download('knight-school-backup-'+day()+'.json',JSON.stringify(backup,null,2),'application/json')}catch(e){toast('Backup could not be created: '+e.message)}}
function showRestore(){
 let restoreGeneration=0;restoreCandidate=null;modal(`<p class="eyebrow">BACKUP & RESTORE</p><h2>Bring your training back.</h2><p>Choose a Knight School JSON backup, or paste one below. The file is checked before anything changes. Restore merges records and keeps your current device settings.</p><label class="secondary" for="backupFile">Choose backup file</label><input id="backupFile" type="file" accept=".json,application/json" hidden><label class="mini-label" for="backupText">Or paste backup JSON</label><textarea id="backupText" class="prompt-fallback" placeholder="Paste your backup JSON here…"></textarea><button class="secondary" id="previewBackup">Check backup</button><p id="restoreStatus" role="status"></p><div id="restoreSummary"></div><button class="primary" id="applyBackup" disabled>Back up current data & merge</button><p class="notice">A safety backup of current data downloads before the merge. Legacy progress-only exports are also accepted. Counts use the larger value to avoid double-counting repeated imports.</p>`);
 function check(text,generation=restoreGeneration){if(generation!==restoreGeneration||!$('#restoreStatus'))return;try{restoreCandidate=parseBackup(text);const p=restoreCandidate.records['knight-school-v1'],t=restoreCandidate.records[trainingKey];$('#restoreSummary').innerHTML=`<div class="coach-note"><b>Ready to merge</b><p>${Object.keys(restoreCandidate.records).length} records · ${p?.done.length||0} completed lessons · ${t?.mistakes.length||0} saved mistakes · ${Object.keys(t?.reviews||{}).length} opening schedules</p></div>`;$('#restoreStatus').textContent='Backup validated. Existing records will be retained.';$('#applyBackup').disabled=false}catch(e){restoreCandidate=null;$('#applyBackup').disabled=true;$('#restoreSummary').innerHTML='';$('#restoreStatus').textContent=e.message}}
 $('#previewBackup').onclick=()=>{restoreGeneration++;check($('#backupText').value)};$('#backupText').oninput=()=>{restoreGeneration++;restoreCandidate=null;$('#applyBackup').disabled=true};
 $('#backupFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;const generation=++restoreGeneration;restoreCandidate=null;$('#applyBackup').disabled=true;$('#restoreStatus').textContent='Reading backup…';if(file.size>8*1024*1024){$('#restoreStatus').textContent='Choose a backup smaller than 8 MB.';restoreCandidate=null;$('#applyBackup').disabled=true;return}try{check(await file.text(),generation)}catch{$('#restoreStatus').textContent='Safari could not read that file. Try pasting its JSON instead.'}};
 $('#applyBackup').onclick=()=>{
  if(!restoreCandidate)return;try{saveChats();saveQuestionSessions();const current=makeBackup(localStorage);download('knight-school-before-restore-'+day()+'.json',JSON.stringify(current,null,2),'application/json');restoreBackup(localStorage,restoreCandidate);rehydrateTraining();$('#modal').close();toast('Backup merged. Your lessons, history and settings are ready.')}catch(e){$('#restoreStatus').textContent=e.message}
 };
}
function rehydrateTraining(){const prefs=loadNarrationSettings(localStorage);voiceURI=prefs.voiceURI;voiceRate=prefs.rate;narrationScope=prefs.scope;studySession=loadStudySession(localStorage);teachAnswers.clear();for(const [k,v]of studySession.answers)teachAnswers.set(k,v);progress=JSON.parse(localStorage.getItem('knight-school-v1'))||progress;training=loadTraining(localStorage);for(const [map,key]of [[coachThreads,'knight-school-chats-v2'],[questionSessions,'knight-school-questions-v1']]){map.clear();for(const [id,v]of JSON.parse(localStorage.getItem(key)||'[]'))map.set(id,key.includes('questions')?makeQuestionState(v):v)}const theme=localStorage.getItem('knight-school-board-theme');if(theme)document.documentElement.dataset.boardTheme=theme;updateTop();if($('#lessonPanel')){renderBoard();renderPanel()}else catalogOrPage()}
document.addEventListener('click',e=>{
 const progressButton=e.target.closest('[data-training-progress]');if(progressButton){progressModal();return}
 const rating=e.target.closest('[data-recall-grade]');if(rating&&pendingRecallResult){const r=pendingRecallResult;training.reviews[reviewKey(r.lessonId,r.side)]=scheduleReview(r.previous,{lessonId:r.lessonId,side:r.side,grade:rating.dataset.recallGrade,now:r.now});persistTraining();renderPanel();return}
 const due=e.target.closest('[data-due-review]');if(due){const r=training.reviews[due.dataset.dueReview];if(!r)return;$('#modal').close();page='openings';history.replaceState(null,'','#openings');renderNav();openStudy(r.lessonId);drillSide=r.side;$('#drillSide').value=r.side;startDrill();return}
 const mistake=e.target.closest('[data-mistake-study]');if(mistake){const m=training.mistakes.find(x=>x.id===mistake.dataset.mistakeStudy);if(!m)return;$('#modal').close();pendingPracticeFen=m.fenBefore;pendingMistakeId=m.id;if(page==='practice')practice();else navigate('practice')}
});

initPWA(modal);


function teachCatalog(){resetContext();teachBranch=null;$('#main').innerHTML=heading('TEACH ME','Understand first. Then practice.','10 practical opening courses for both sides. These are teaching choices, not a ranking of winning strength.')+resumeStudyMarkup()+'<p>Start with Italian or London as White; Caro-Kann or Queen’s Gambit structures as Black. Each course explains the moves, compares a real alternative, checks understanding, then connects to tactics and endings.</p><div class="catalog">'+teachCourses.map(c=>`<article class="catalog-card"><span class="pill">OPENING → PLAN → PRACTICE</span><h3>${esc(c.name)}</h3><p>${esc(c.intro)}</p><button class="primary" data-teach-open="${c.id}">Teach me this opening →</button></article>`).join('')+'</div><h2 style="margin-top:28px">From opening to winning a game</h2><p>A good opening gives you playable positions. These next chapters teach how to use them.</p><div class="button-row"><button class="secondary" data-open="development">Middlegame 1: improve your pieces</button><button class="secondary" data-open="fork">Middlegame 2: find forcing threats</button><button class="secondary" data-open="opposition">Endgame 1: use your king</button><button class="secondary" data-open="lucena">Endgame 2: convert a rook ending</button></div>';}
function teachMarkup(){const c=teachCourses.find(c=>c.id===(lesson?.courseId||lesson?.id));if(!c)return '';const controls=teachModeControls(c);if(teachPlanMode)return controls+planningMarkup(c);if(drill)return controls+'<section class="teach-card" aria-label="Test mode"><h2>Recall the opening</h2><p>Arrows and explanations are hidden. Play the studied moves; use Hint when stuck. Missed moves and hints affect your existing spaced-review schedule.</p><button class="secondary" data-action="hint">Give me a hint</button></section>';const quiz=lesson.courseId?{question:'What changes when '+lesson.line.split(' ')[openingBranches.find(b=>b.id===lesson.id).prefixCount]+' is played in this branch?',choices:[lesson.branchNotes[openingBranches.find(b=>b.id===lesson.id).prefixCount],'It guarantees a win regardless of the opponent’s reply.','It means both players should stop developing.'],answer:0}:c;const answered=teachAnswers.get(lesson.id),finished=step>=line.length;return controls+`<section class="teach-card" aria-label="Teach Me lesson"><span class="pill">TEACH ME · ${Math.min(step,line.length)} / ${line.length} HALF-MOVES</span><h2>${esc(c.name)}: the idea</h2>${teachNextTheoryMarkup()}<p>${esc(c.plain)}</p><h3>${step===0?'Before the first move':side(lastMove?.color||'w')+' played '+(lastMove?.san||'')}</h3><p>${esc(teachBranch?c.comparison:generalNote())}</p><details><summary>Go deeper: structure, plans and tradeoffs</summary><p>${esc(c.deep)}</p><p>${esc(getOpeningTheory(c.name)?.white||'')}</p><p>${esc(getOpeningTheory(c.name)?.black||'')}</p><p><b>Words to know:</b> Development means bringing pieces into useful play. A pawn break challenges the opposing pawn structure. An outpost is a useful square an enemy pawn cannot easily attack. A half-open file has no pawn of one color; rooks can use it.</p></details><details><summary>Why not a different move?</summary><p>Compare ${esc(c.main)} with ${esc(c.alternative.split(' ')[0])} after ${esc(c.prefix)}. Both are playable choices; this example explains the tradeoff.</p><p>${esc(c.comparison)}</p><button class="secondary" data-teach-compare>Show alternative on the board</button></details>${teachBranch?'<p role="status">Alternative demonstration. Return to the lesson before continuing.</p><button class="primary" data-teach-return>Return to lesson</button>':`<div class="button-row"><button class="primary" data-teach-continue>${finished?'Restart walkthrough':'Continue lesson →'}</button></div>`}${finished?`<button class="primary" data-teach-plan>Choose the middlegame plan →</button><button class="secondary" data-opening-practice>Practice beyond the opening →</button><h3>Check your understanding</h3><p>${esc(quiz.question)}</p><div class="teach-choices">${quiz.choices.map((x,i)=>`<button class="secondary" data-teach-answer="${i}">${esc(x)}</button>`).join('')}</div>${answered!==undefined?`<p role="status">${answered===quiz.answer?'Correct. '+esc(quiz.choices[quiz.answer])+'. Explain that idea aloud before practicing.':'Try again. Re-read the plain-language idea and compare what the move actually controls.'}</p>`:''}<button class="secondary" data-action="drill">Practice this opening →</button><p>Next: choose a middlegame or endgame chapter from Teach Me. Your regular opening drill still schedules spaced reviews.</p>`:''}</section>`;}
document.addEventListener('click',e=>{const open=e.target.closest('[data-teach-open]');if(open){teachBranch=null;openStudy(open.dataset.teachOpen);return}if(page!=='teach')return;const c=teachCourses.find(c=>c.id===(lesson?.courseId||lesson?.id));if(!c)return;if(e.target.closest('[data-teach-compare]')){pausePlayback();stopEngine();teachBranch={step};chess=new Chess();for(const mv of (c.prefix+' '+c.alternative).split(' '))chess.move(mv);teachBranch.fen=chess.fen();lastMove=chess.history({verbose:true}).at(-1);selected=null;legal=[];free=false;renderBoard();renderPanel();return}if(e.target.closest('[data-teach-return]')){step=teachBranch?.step||0;teachBranch=null;setPosition();renderBoard();renderPanel();return}if(e.target.closest('[data-teach-continue]')){teachBranch=null;step=step>=line.length?0:step+1;setPosition();renderBoard();renderPanel();$('#lessonPanel').scrollIntoView({block:'start',behavior:'smooth'});return}const answer=e.target.closest('[data-teach-answer]');if(answer){teachAnswers.set(lesson.id,Number(answer.dataset.teachAnswer));renderPanel()}});

function teachBridgeMarkup(){const chapters={development:['Improve your least useful piece','After developing and castling, do not attack just because the opening moves are finished. Ask which piece has no useful job. Improve it toward a square that supports a central break or restrains an enemy piece. First check forcing threats: an immediate check or hanging piece can override a long-term plan.','Before choosing a plan, compare king safety, material, active pieces and pawn weaknesses. If your opponent has a lead in development, opening files can help them more than you. A good maneuver should have a destination and a purpose, not merely move a piece twice.'],fork:['Calculate forcing moves','A fork attacks two targets at once. A checking fork is especially powerful because the opponent must answer the check before saving another piece. Look at the squares your knight attacks from its destination, not just its starting square.','Calculate in order: your candidate, their strongest forcing reply, your continuation. Count whether the forking piece can be captured legally. A geometric attack by a pinned piece is not automatically a legal capture. Use the board exercise below, then try the idea from the opposite side.'],opposition:['Make the king an active piece','With queens and many pieces gone, the king can support a pawn and stop the opposing king. Opposition means arranging the kings so the opponent must give way. It depends on whose turn it is, not merely on the kings looking symmetrical.','Do not push a pawn before checking whether its king can escort it. Count both promotion races, check whether the enemy king can catch the pawn, and watch for stalemate. In pawn endings one wasted tempo can change a win into a draw.'],lucena:['Turn a winning idea into a technique','A rook ending is not won simply because a pawn is close to promotion. Your king needs shelter from checks and your rook needs an active job. In this example the fourth-rank rook move prepares a bridge: later it can block the defender’s checks.','Follow the illustrative line slowly. Notice when the attacking king leaves the promotion square, how the defender checks from a distance, and where the rook can interpose. If Black changes the checking pattern, calculate again. The pattern guides your search; it does not replace checking legal replies.']};const x=chapters[lesson?.id];return x?`<section class="teach-card" aria-label="Teach Me transfer chapter"><span class="pill">OPENING → MIDDLEGAME → ENDGAME</span><h2>${esc(x[0])}</h2><p>${esc(x[1])}</p><details><summary>Go deeper: make the decision yourself</summary><p>${esc(x[2])}</p></details><p>Read the task below, try the move on the board, then reveal the line and explain why it works. Use Stockfish to test other replies.</p></section>`:''}

function renderBoardGuidance(){if(!$('#boardGuidanceLayer'))return;const data=boardGuidance({fen:chess.fen(),analysis:engineResult,lastMove,nextMove:nextLessonMove(),lessonAttempt,lessonMove:!deviationState&&!practiceRecall&&!replyDemo&&!teachPlanMode&&!teachBranch&&!guidancePreview&&!!lesson&&!['practice','review'].includes(lessonType)&&page!=='practice',hidden:!showBoardGuidance||drill||playing});$('#boardGuidanceLayer').innerHTML=guidanceSvg(data,flipped);$('#boardGuidanceCaption').textContent=!showBoardGuidance?'Board teaching hidden.':drill||playing?'Hints hidden while you practice.':data.caption||'Open a lesson for the next-move arrow, or analyze with Stockfish for engine guidance.';if(autoExplain&&!drill&&!playing){const n=nextAutomaticExplanation();if(n&&showBoardGuidance)$('#boardGuidanceCaption').textContent+=' Why: '+n.reason}const b=$('[data-guidance-toggle]');b.setAttribute('aria-pressed',String(showBoardGuidance));$('#guidanceReviewControls').innerHTML=replyDemo?replyDemoMarkup():guidancePreview?'<button class="secondary" data-guidance-return>Return to my move</button>':!drill&&!playing&&engineResult?.fen===chess.fen()&&engineResult?.moveReview&&lastMove?'<button class="secondary" data-guidance-before>Show my earlier better candidate</button>'+ (engineResult.lines?.[0]?.uci?.length?'<button class="primary" data-reply-demo>Show opponent’s reply</button>':''):'';}
document.addEventListener('click',e=>{if(e.target.closest('[data-guidance-toggle]')){showBoardGuidance=!showBoardGuidance;renderBoardGuidance();return}if(e.target.closest('[data-guidance-before]')){const m=chess.history({verbose:true}).at(-1),before=engineResult?.moveReview?.before;if(!m||!before?.length)return;pausePlayback();guidancePreview={chess,lastMove,engineResult,step,free};chess=new Chess(m.before);lastMove=null;selected=null;legal=[];engineResult={fen:chess.fen(),lines:before,whiteScore:before[0].scoreWhite||0,mate:before[0].mateWhite??null,depth:before[0].depth,explain:'Earlier candidate before your move. Return to your move to continue.'};renderBoard();renderPanel();return}if(e.target.closest('[data-guidance-return]')&&guidancePreview){({chess,lastMove,engineResult,step,free}=guidancePreview);guidancePreview=null;selected=null;legal=[];renderBoard();renderPanel()}});

function nextLessonMove(){if(deviationState)return deviationNextMove();if(practiceRecall)return null;if(replyDemo||teachPlanMode)return null;if(drill||playing||free||teachBranch||guidancePreview||!lesson||lessonType==='review'||page==='practice'||step>=line.length)return null;try{const m=new Chess(chess.fen()).move(line[step]);return {san:m.san,from:m.from,to:m.to}}catch{return null}}
function teachNextTheoryMarkup(){const next=nextLessonMove();if(!next)return '<p>Walkthrough finished, or exploring an alternative. Return to the taught line to continue.</p>';const theory=getOpeningTheory(lesson.name),why=(lesson.branchNotes||theory?.notes)?.[step];return `<section class="teach-next" aria-label="Your next opening move"><span class="pill">YOUR TURN · ${side(chess.turn())}</span><h3>Play ${esc(next.san)}: ${esc(next.from)} → ${esc(next.to)}</h3><p><b>Why this move?</b> ${esc(why||'Follow the illustrated line and compare the position with the plans below.')}</p><p>Move the piece on the board. The green arrow points to its destination. Learn both sides before testing your memory with Practice.</p>${lessonAttempt?`<p role="status"><b>${lessonAttempt.correct?'✓ Correct':'× Try again'}</b> ${esc(feedback)}</p>`:''}<details><summary>Connect this move to the theory</summary><p><b>Pawn structure and tradeoffs:</b> ${esc(theory?.structure||'')}</p><p><b>White’s long-term plan:</b> ${esc(theory?.white||'')}</p><p><b>Black’s long-term plan:</b> ${esc(theory?.black||'')}</p><p>After every move, check what changed: central control, development, king safety, and the opponent’s forcing replies. A familiar opening move can still be wrong in a different position.</p></details></section>`}

function teachModeControls(c){return `<section class="teach-card" aria-label="Learning mode and branch"><div class="button-row teach-navigation"><button class="secondary" data-teach-home>← All courses</button><button class="secondary" data-teach-restart>↺ Restart this line</button></div><h3>Choose how to learn</h3><button class="secondary" data-deviation-open="${deviationLessons.find(d=>d.courseId===c.id)?.id||''}">What if my opponent plays something else? →</button><div class="button-row"><button class="${drill?'secondary':'primary'}" data-teach-learn aria-pressed="${!drill}">Learn · arrows & theory</button><button class="${drill?'primary':'secondary'}" data-teach-test aria-pressed="${drill}">Test · recall from memory</button></div><label for="teachBranchSelect">Opening response</label><select id="teachBranchSelect" aria-label="Opening response"><option value="${c.id}" ${lesson.id===c.id?'selected':''}>Main course line</option>${teachBranchLessons.filter(x=>x.courseId===c.id).map(x=>`<option value="${x.id}" ${lesson.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><label for="teachTestSide">Test as</label><select id="teachTestSide" aria-label="Test as"><option value="w" ${drillSide==='w'?'selected':''}>White</option><option value="b" ${drillSide==='b'?'selected':''}>Black</option><option value="both" ${drillSide==='both'?'selected':''}>Both sides</option></select><p>Learn both sides step by step. Each response and side has its own recall schedule.</p></section>`}
document.addEventListener('change',e=>{if(e.target.id==='teachBranchSelect'){const testing=drill;openStudy(e.target.value);if(testing)startDrill()}});
document.addEventListener('click',e=>{if(e.target.closest('[data-teach-test]')){deviationState=null;teachPlanMode=false;teachBranch=null;drillSide=$('#teachTestSide').value;if($('#drillSide'))$('#drillSide').value=drillSide;startDrill()}if(e.target.closest('[data-teach-learn]')){deviationState=null;drill=false;step=0;feedback='';teachBranch=null;setPosition();renderBoard();renderPanel()}});

document.addEventListener('change',e=>{if(e.target.id==='teachTestSide'){drillSide=e.target.value;if($('#drillSide'))$('#drillSide').value=drillSide;if(drill)startDrill()}});

// A selected sidebar section is also a reliable way back to its landing page.
document.addEventListener('click',e=>{const link=e.target.closest('#nav a');if(link&&link.hash===location.hash){e.preventDefault();route();return}if(e.target.closest('[data-teach-home]')){teachCatalog();window.scrollTo(0,0);return}if(e.target.closest('[data-teach-restart]')){deviationState=null;pausePlayback();teachBranch=null;if(drill)startDrill();else{step=0;feedback='';feedbackError=false;setPosition();renderBoard();renderPanel()}$('#lessonPanel')?.scrollIntoView({block:'start',behavior:'smooth'})}});


// Browser-local teaching helpers. No remote AI or narration service is used.
function narrationMarkup(){return `<details class="narration-tools"><summary>🔊 Listen to the explanation</summary><p>Hear the current move and its explanation. Buttons, menus and progress labels are never included. Voice quality depends on the voices your device makes available.</p><div class="button-row"><button class="secondary" data-narrate="test" ${drill?'disabled':''}>Test voice</button><button class="primary" data-narrate="read" ${drill?'disabled':''}>Explain aloud</button><button class="secondary" data-narrate="pause">Pause / resume</button><button class="secondary" data-narrate="repeat" ${drill?'disabled':''}>Repeat</button><button class="secondary" data-narrate="stop">Stop</button></div><label class="auto-explain-option"><input type="checkbox" id="autoExplainNext" ${autoExplain?'checked':''}> Auto-explain next move</label><p>Turn on once for this visit. After each lesson move, the arrow and voice explain the next taught move. Piece selection and panel updates do not repeat it. Stop turns this off; tests and engine games keep hints hidden.</p><label for="narrationScope">What to hear</label><select id="narrationScope"><option value="move" ${narrationScope==='move'?'selected':''}>Current move & reason</option><option value="theory" ${narrationScope==='theory'?'selected':''}>Move, deeper theory & both plans</option></select><details class="spoken-preview"><summary>Preview the spoken explanation</summary><p id="narrationTextPreview">${esc(currentNarration())}</p></details><label for="narrationVoice">Voice · English choices first</label><select id="narrationVoice">${localVoiceOptions()}</select><button class="secondary" data-narrate="refresh">Refresh voices</button><label for="narrationRate">Reading speed</label><select id="narrationRate">${[.75,.9,1,1.1,1.25].map(v=>`<option value="${v}" ${v===voiceRate?'selected':''}>${v}×</option>`).join('')}</select><p id="narrationStatus" role="status">${esc(drill?'Written and spoken explanations are hidden during recall.':narrator.status()&&narrator.status()!=='Stopped.'?narrator.status():narrator.availability())}</p><details><summary>Improve voice quality on iPhone</summary><p>Try the named English voices above using Test voice. Enhanced or Premium voices may sound more natural if your iPhone exposes them here. Your choice and speed are saved on this device.</p><p>You can download enhanced voices in iPhone Accessibility settings. After downloading, reopen Safari, tap Refresh voices and choose the voice if it appears. Safari may expose a different list from other Apple apps.</p><a href="https://support.apple.com/en-us/111798" target="_blank" rel="noopener noreferrer">Apple’s voice setup instructions ↗</a><p>These are device or browser voices, not a newly generated custom voice. A voice marked “browser service” or Browser default may use your browser’s speech service when you tap a speech button. Knight School makes no paid AI calls.</p></details></details>`}
function localVoiceOptions(){const choices=narrator.voiceOptions(),selected=selectedVoiceURI(choices,voiceURI);return choices.map(v=>`<option value="${esc(v.voiceURI)}" ${v.voiceURI===selected?'selected':''}>${esc(v.name)} (${esc(v.lang)}) · ${v.localService===true?'on device':'browser service'}</option>`).join('')+`<option value="__default__" ${selected==='__default__'?'selected':''}>Browser default</option>`}
function refreshVoiceChoices(){if($('#narrationVoice'))$('#narrationVoice').innerHTML=localVoiceOptions();if($('#narrationStatus'))$('#narrationStatus').textContent=narrator.availability()}
window.speechSynthesis?.addEventListener('voiceschanged',refreshVoiceChoices);
function currentNarrationContext(){
 if(drill)return {hidden:true};
 const e=explainMove(chess,lesson),theory=e.theory||getOpeningTheory(lesson?.name),plans={theory:theory?.structure||'',whitePlan:planText(chess,'w',lesson),blackPlan:planText(chess,'b',lesson)};
 if(replyDemo)return {lead:replyDemoExplanation(),allowTheory:false};
 if(practiceRecall){const r=practiceRecall.review;return practiceRecall.solved?{lead:`${side(r.move.color)}: a better response to ${r.move.san}.`,reason:r.explanation,allowTheory:false}:{lead:`${side(r.move.color)} to move. Find a better move than ${r.move.san}.`,reason:'Look for checks, captures and threats.',allowTheory:false}}
 if(openingPractice){const r=openingPractice.review;if(r)return {lead:`${side(r.move.color)} played ${r.move.san}.`,reason:r.explanation,allowTheory:false};return {...plans,lead:`${side(chess.turn())} to move.`,reason:chess.history().length?generalNote():openingPractice.side==='w'?openingPractice.white:openingPractice.black}}
 if(deviationState){const d=currentDeviation(),c=d.choices[deviationState.choice],base=deviationBoard(d),m=base.history({verbose:true}).at(-1);return {...plans,lead:c?`The illustrated response is ${c.move}.`:`${side(m.color)} played ${m.san}. ${side(base.turn())} responds.`,reason:c?c.why+(deviationState.cursor>1?' '+side(lastMove.color)+' then played '+lastMove.san+'. '+explainMove(chess,null).facts.join(' '):''):d.idea,allowTheory:!!c}}
 if(teachPlanMode){const p=planningLessons[lesson?.courseId||lesson?.id],answered=teachAnswers.has('plan:'+lesson.id);return {...plans,lead:p.question,reason:answered?p.why:'',allowTheory:answered}}
 const course=teachCourses.find(c=>c.id===(lesson?.courseId||lesson?.id));if(teachBranch&&course)return {...plans,lead:'Compare the alternative.',reason:course.comparison,theory:course.deep};
 const next=nextLessonMove();if(page==='teach'&&lessonType==='opening'&&next)return {...plans,lead:`${side(chess.turn())} to move. The course move is ${next.san}.`,reason:(lesson.branchNotes||theory?.notes)?.[step]||course?.plain||'',theory:[course?.deep,theory?.structure].filter(Boolean).join(' ')};
 return {...plans,lead:lastMove?`${side(lastMove.color)} played ${lastMove.san}.`:`${side(chess.turn())} to move.`,reason:engineResult?.fen===chess.fen()&&engineResult.moveReview?[engineResult.moveReview.summary,engineResult.explain].filter(Boolean).join(' '):engineResult?.fen===chess.fen()?engineResult.explain:generalNote()};
}
function currentNarration(){return buildNarration(currentNarrationContext(),narrationScope)}
function persistNarrationPreferences(){try{saveNarrationSettings(localStorage,{voiceURI,rate:voiceRate,scope:narrationScope})}catch{}}
function narrationOptions(){voiceURI=$('#narrationVoice')?.value||voiceURI;persistNarrationPreferences();return {voiceURI,rate:voiceRate,allowBrowserDefault:voiceURI==='__default__',allowBrowserVoice:voiceURI!=='__default__'&&narrator.voiceOptions().some(v=>v.voiceURI===voiceURI&&v.localService!==true)}}
function rememberStudy(){if(deviationState){rememberDeviation();return;}if(!teachCourses.some(c=>c.id===(lesson?.courseId||lesson?.id))||restoringStudy||replyDemo||page!=='teach'||lessonType!=='opening'||free||teachBranch||guidancePreview)return;studySession={version:1,last:{id:lesson.id,step,side:drillSide,mode:drill?'test':teachPlanMode?'plan':'learn',errors:drillErrors,hints:drillHints,updatedAt:new Date().toISOString()},answers:[...teachAnswers]};try{saveStudySession(localStorage,studySession)}catch{toast('Lesson could not be saved on this device. Keep this tab open.')}}
function resumeStudyMarkup(){const r=studySession.last;if(!r||![...families,...teachBranchLessons].some(x=>x.id===r.id))return '';return `<section class="teach-card"><h3>Pick up where you left off</h3><p>${esc(studyName(r.id))} · ${esc(r.mode)} · half-move ${r.step}</p><button class="primary" data-study-resume>Resume learning →</button></section>`}
function resumeStudy(){const r={...studySession.last};if(r.mode==='deviation'){openDeviation(r.deviation.id,{...r.deviation,courseStep:r.step});return;}const item=[...families,...teachBranchLessons].find(x=>x.id===r.id);if(!item||r.step>movesFor(item.line).length){toast('That saved lesson changed. Please choose a course.');return}restoringStudy=true;try{openStudy(r.id,r.step);drillSide=r.side;drill=r.mode==='test';teachPlanMode=r.mode==='plan';drillErrors=r.errors;drillHints=r.hints;renderBoard();renderPanel()}finally{restoringStudy=false}rememberStudy();$('#lessonPanel')?.scrollIntoView({block:'start'})}
function planningMarkup(c){const p=planningLessons[c.id],key='plan:'+lesson.id,a=teachAnswers.get(key);return `<section class="teach-card" aria-label="Choose the plan"><span class="pill">OPENING → MIDDLEGAME · ${esc(p.focus)}</span><h2>Choose the plan</h2><p>Study the final position of the main course line. These are strategic choices, not claims of one forced best move.</p><h3>${esc(p.question)}</h3><div class="teach-choices">${p.choices.map((x,i)=>`<button class="secondary" data-plan-answer="${i}">${esc(x)}</button>`).join('')}</div>${a!==undefined?`<p role="status"><b>${a===p.answer?'Correct plan.':'Reconsider that plan.'}</b> ${esc(p.why)}</p><p>Before moving: name your opponent’s strongest threat, your least active piece, and the pawn break you are preparing.</p>`:'<p>Choose a plan to reveal the reasoning.</p>'}<button class="secondary" data-teach-learn>Back to opening walkthrough</button><button class="secondary" data-action="analyze">Compare with free Stockfish</button><button class="primary" data-opening-practice>Practice this plan against Stockfish →</button>${engineBox()}</section>`}
function replyDemoMarkup(){return `<section class="reply-demo" aria-label="Engine reply demonstration"><h3>See why the reply matters · ${replyDemo.cursor} / ${replyDemo.moves.length}</h3><p>${esc(replyDemoExplanation())}</p><p>Illustrative short-search continuation, not a forced proof. Your original position is preserved.</p><div class="button-row"><button class="secondary" data-demo-back ${replyDemo.cursor===0?'disabled':''}>← Back</button><button class="primary" data-demo-next ${replyDemo.cursor>=replyDemo.moves.length?'disabled':''}>Next reply →</button><button class="secondary" data-demo-return>Return to my position</button></div></section>`}
function replyDemoExplanation(){if(!replyDemo?.cursor)return 'This is the position after your move. Play the engine’s suggested reply and inspect the consequence.';const m=chess.history({verbose:true}).at(-1);return `${side(m.color)} plays ${m.san}. `+explainMove(chess,null).facts.join(' ')}
function showReplyDemo(){if(drill||playing||engineResult?.fen!==chess.fen())return;const moves=engineResult.lines?.[0]?.uci?.slice(0,6);if(!moves?.length)return;const probe=new Chess(chess.fen()),legalMoves=[];for(const u of moves){try{probe.move({from:u.slice(0,2),to:u.slice(2,4),promotion:u[4]||'q'});legalMoves.push(u)}catch{break}}if(!legalMoves.length)return;pausePlayback();narrator.stop();replyDemo={original:{chess,lastMove,engineResult,step,free},fen:chess.fen(),moves:legalMoves,cursor:0};engineResult=null;selected=null;legal=[];free=true;renderBoard();renderPanel()}
function stepReplyDemo(delta){if(!replyDemo)return;replyDemo.cursor=Math.max(0,Math.min(replyDemo.moves.length,replyDemo.cursor+delta));chess=new Chess(replyDemo.fen);for(const u of replyDemo.moves.slice(0,replyDemo.cursor))chess.move({from:u.slice(0,2),to:u.slice(2,4),promotion:u[4]||'q'});lastMove=chess.history({verbose:true}).at(-1)||null;renderBoard();renderPanel()}
document.addEventListener('change',e=>{if(e.target.id==='narrationVoice'){narrator.stop();voiceURI=e.target.value;persistNarrationPreferences()}if(e.target.id==='narrationRate'){narrator.stop();voiceRate=Number(e.target.value);persistNarrationPreferences()}if(e.target.id==='narrationScope'){narrator.stop();narrationScope=e.target.value;persistNarrationPreferences();if($('#narrationTextPreview'))$('#narrationTextPreview').textContent=currentNarration()}});
document.addEventListener('click',e=>{const speech=e.target.closest('[data-narrate]');if(speech){const action=speech.dataset.narrate;if(action==='stop'){autoExplain=false;autoExplainPaused=false;if($('#autoExplainNext'))$('#autoExplainNext').checked=false;narrator.stop();}if(action==='refresh')refreshVoiceChoices();if(!drill&&action==='test'){pausePlayback();narrator.read('Develop your pieces, protect your king, and check your opponent’s threats.',narrationOptions())}if(action==='pause'){if(autoExplain)autoExplainPaused=!autoExplainPaused;narrator.pause();}if(!drill&&action==='repeat'){pausePlayback();narrator.read(currentNarration(),narrationOptions())}if(!drill&&action==='read'){pausePlayback();narrator.read(currentNarration(),narrationOptions())}return}if(e.target.closest('[data-study-resume]')){resumeStudy();return}if(e.target.closest('[data-teach-plan]')){const c=teachCourses.find(x=>x.id===(lesson?.courseId||lesson?.id));if(!c)return;openStudy(c.id,movesFor(families.find(x=>x.id===c.id).line).length);teachPlanMode=true;renderBoard();renderPanel();$('#lessonPanel').scrollIntoView({block:'start'});return}const answer=e.target.closest('[data-plan-answer]');if(answer){teachAnswers.set('plan:'+lesson.id,Number(answer.dataset.planAnswer));renderPanel();return}if(e.target.closest('[data-reply-demo]'))showReplyDemo();if(e.target.closest('[data-demo-next]'))stepReplyDemo(1);if(e.target.closest('[data-demo-back]'))stepReplyDemo(-1);if(e.target.closest('[data-demo-return]')&&replyDemo){({chess,lastMove,engineResult,step,free}=replyDemo.original);replyDemo=null;renderBoard();renderPanel()}});


function currentDeviation(){return deviationLessons.find(d=>d.id===deviationState?.id)}
function openDeviation(id,saved=null){const record=deviationLessons.find(d=>d.id===id);if(!record)return;const courseStep=Number.isInteger(saved?.courseStep)?Math.min(saved.courseStep,movesFor(families.find(f=>f.id===record.courseId).line).length):lesson?.id===record.courseId?step:0;openStudy(record.courseId,courseStep);deviationState={id,courseStep,choice:null,cursor:0,attempt:''};if(saved&&Number.isInteger(saved.choice)&&record.choices[saved.choice]&&Number.isInteger(saved.cursor)&&saved.cursor>=0&&saved.cursor<=record.choices[saved.choice].line.length){deviationState.choice=saved.choice;deviationState.cursor=saved.cursor}showDeviationPosition()}
function showDeviationPosition(){pausePlayback();narrator.stop();stopEngine();chess=deviationBoard(currentDeviation(),deviationState.choice,deviationState.cursor);lastMove=chess.history({verbose:true}).at(-1)||null;selected=null;legal=[];lessonAttempt=null;free=true;renderBoard();renderPanel()}
function chooseDeviation(index){const d=currentDeviation();if(!d?.choices[index])return;deviationState.choice=index;deviationState.cursor=1;deviationState.attempt='';showDeviationPosition()}
function attemptDeviation(move){if(deviationState.choice!==null){toast('Use Retry decision before choosing another move.');return}try{const probe=new Chess(chess.fen()),m=probe.move(move),i=currentDeviation().choices.findIndex(c=>c.move===m.san);if(i>=0)chooseDeviation(i);else{deviationState.attempt=m.san+' is legal but is not one of this exercise’s three illustrated choices. It has not been graded. Choose a listed response or analyze the position with Stockfish.';selected=null;legal=[];renderBoard();renderPanel()}}catch{}}
function stepDeviation(delta){const c=currentDeviation()?.choices[deviationState?.choice];if(!c){toast('Choose a response first.');return}deviationState.cursor=Math.max(0,Math.min(c.line.length,deviationState.cursor+delta));showDeviationPosition()}
function retryDeviation(){if(!deviationState)return;deviationState.choice=null;deviationState.cursor=0;deviationState.attempt='';showDeviationPosition()}
function deviationNextMove(){const c=currentDeviation()?.choices[deviationState?.choice],san=c?.line[deviationState.cursor];if(!san)return null;try{const m=new Chess(chess.fen()).move(san);return {san:m.san,from:m.from,to:m.to}}catch{return null}}
function deviationMarkup(){const d=currentDeviation(),c=d.choices[deviationState.choice],base=deviationBoard(d),opponent=base.history({verbose:true}).at(-1),course=teachCourses.find(x=>x.id===d.courseId);return teachModeControls(course)+`<section class="teach-card" id="deviationLesson" aria-label="Opponent deviation"><span class="pill">READ THE POSITION · CHOOSE · SEE WHY</span><h2>What if they play something else?</h2><label for="deviationSelect">Decision exercise</label><select id="deviationSelect">${deviationLessons.filter(x=>x.courseId===d.courseId).map(x=>`<option value="${x.id}" ${x.id===d.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select><h3>${esc(d.title)}</h3><p>${side(opponent.color)} played <b>${esc(opponent.san)}</b>. ${side(base.turn())} responds.</p><p>${esc(d.idea)}</p><p>Choose a move below or play one of these choices on the board. A different legal move is not automatically a mistake.</p><div class="teach-choices">${d.choices.map((x,i)=>`<button class="secondary" data-deviation-choice="${i}" aria-pressed="${deviationState.choice===i}">${esc(x.move)} · ${esc(x.label)}</button>`).join('')}</div>${c?`<p role="status"><b>${c.kind==='recommended'?'The teaching plan':c.kind==='playable'?'A playable alternative':'A tradeoff to inspect'}: ${esc(c.move)}.</b> ${esc(c.why)}</p><h3>Watch the consequence · ${deviationState.cursor} / ${c.line.length}</h3><p>${deviationState.cursor?esc(side(lastMove.color)+' played '+lastMove.san+'. '+explainMove(chess,null).facts.join(' ')):'The original decision position is restored. Step forward to see the chosen continuation.'}</p><p>Illustrative line; your opponent may choose another legal reply. Use Stockfish to compare, rather than treating this as a forced result.</p><div class="button-row"><button class="secondary" data-deviation-prev ${deviationState.cursor===0?'disabled':''}>← Back one move</button><button class="primary" data-deviation-next ${deviationState.cursor===c.line.length?'disabled':''}>Show next move →</button><button class="secondary" data-deviation-retry>Retry decision</button></div>`:'<p>The continuation and its arrow stay hidden until you choose.</p>'}${deviationState.attempt?`<p role="status">${esc(deviationState.attempt)}</p>`:''}<div class="button-row"><button class="primary" data-opening-practice>Practice this position against Stockfish →</button><button class="secondary" data-deviation-return>Return to opening lesson</button><button class="secondary" data-action="analyze">Compare with free Stockfish</button></div>${engineBox()}</section>`}
function rememberDeviation(){const d=currentDeviation();studySession={version:1,last:{id:d.courseId,step:deviationState.courseStep,side:drillSide,mode:'deviation',errors:0,hints:0,updatedAt:new Date().toISOString(),deviation:{id:d.id,choice:deviationState.choice,cursor:deviationState.cursor}},answers:[...teachAnswers]};try{saveStudySession(localStorage,studySession)}catch{}}
function beginOpeningPractice(){const id=lesson?.courseId||lesson?.id;if(!teachCourses.some(c=>c.id===id))return;pendingOpeningPractice={courseId:id,name:studyName(id),fen:chess.fen(),side:deviationState?deviationBoard(currentDeviation()).turn():chess.turn(),white:planText(chess,'w',lesson),black:planText(chess,'b',lesson),returnStep:step,returnMode:teachPlanMode?'plan':'learn',deviation:deviationState?{...deviationState}:null,review:null,busy:false};pendingPracticeFen=chess.fen();pendingMistakeId=null;playSide=pendingOpeningPractice.side;if(page==='practice')practice();else navigate('practice')}
function openingPracticeMarkup(){if(!openingPractice)return '';if(practiceRecall){const r=practiceRecall.review;return `<section class="teach-card" id="openingPracticeCard" aria-label="Practice mistake retry"><span class="pill">YOUR PRACTICE · TRY IT AGAIN</span><h2>Improve on ${esc(r.move.san)}</h2><p>${side(r.move.color)} to move. Find the earlier Stockfish candidate. Another legal move may also be playable.</p>${practiceRecall.solved?'<p role="status">✓ You found the candidate. Explain why it helps before returning to practice.</p>':`<p role="status">${esc(practiceRecall.message||'The answer is hidden. Look for checks, captures and threats.')}</p>`}<details><summary>Reveal candidate and reasoning</summary><p>${esc(r.analysis.moveReview.before[0]?.san[0]||'No candidate')}</p><p>${esc(r.explanation)}</p></details><button class="primary" data-practice-recall-return>Return to practice game</button></section>`}const r=openingPractice.review;return `<section class="teach-card" id="openingPracticeCard" aria-label="Opening practice plan"><span class="pill">USE WHAT YOU LEARNED</span><h2>${esc(openingPractice.name)} · play the plan</h2><p>Choose your side and engine strength below, then tap Play against Stockfish. Before every move, check the opponent’s threat.</p><details><summary>Your starting plans for both sides</summary><p><b>White:</b> ${esc(openingPractice.white)}</p><p><b>Black:</b> ${esc(openingPractice.black)}</p><p>These describe the starting structure. Reassess after exchanges and pawn breaks.</p></details><button class="primary" data-practice-review ${openingPractice.busy?'disabled':''}>${openingPractice.busy?'Reviewing your moves…':'Finish & review my practice'}</button><p role="status">${esc(openingPractice.status||'The short review checks up to your last six moves for the selected side. It does not analyze every move of a long game.')}</p>${r?`<h3>${['mistake','blunder','inaccuracy'].includes(r.grade.code)?'One mistake to learn from':'One useful moment to study'}</h3><p><b>${esc(r.move.san)} · ${esc(r.grade.label)}</b></p><p>${esc(r.explanation)}</p><button class="secondary" data-practice-recall>Retry this earlier position →</button><p>Short Stockfish searches are estimates. ${r.mistakeId?'This position was saved to your Mistake Notebook.':'No mistake was added to the notebook for this move.'}</p>`:''}<button class="secondary" data-practice-course>Return to my opening lesson</button></section>`}
async function finishOpeningReview(){if(!openingPractice||openingPractice.busy)return;const sideToReview=$('#playSide')?.value||playSide,moves=practiceSample(chess,sideToReview);if(!moves.length){openingPractice.status='Play at least one move as the selected side first.';renderPanel();return}playing=false;pausePlayback();stopEngine();const session=openingPractice,token=engineToken;session.busy=true;session.review=null;renderPanel();const reviews=[];try{for(let i=0;i<moves.length;i++){if(token!==engineToken||openingPractice!==session)return;session.status=`Reviewing move ${i+1} of ${moves.length} (${side(sideToReview)}).`;renderPanel();const move=moves[i];let task=searchPosition(move.before,{time:650,multipv:1});engine=task;const before=await task.promise;if(token!==engineToken||openingPractice!==session)return;const afterBoard=new Chess(move.after);let after;if(afterBoard.isGameOver()){after={lines:[{terminal:afterBoard.isCheckmate()?'checkmate':'draw',scoreWhite:afterBoard.isCheckmate()?null:0,mateWhite:afterBoard.isCheckmate()?(afterBoard.turn()==='b'?1:-1):null,uci:[],san:[]}]}}else{task=searchPosition(move.after,{time:650,multipv:1});engine=task;after=await task.promise;if(token!==engineToken||openingPractice!==session)return}reviews.push({move,analysis:{fen:move.after,lines:after.lines,moveReview:{before:before.lines,after:after.lines}}})}const moment=selectPracticeMoment(reviews);if(moment){const report=practiceMomentReport(moment);moment.explanation=[report.summary,...report.alerts.map(a=>a.title+': '+a.text)].join(' ');const board=new Chess(moment.move.before);board.move(moment.move.san);const mistake=createMistake(board,moment.analysis,session.courseId);if(rememberMistake(training,mistake)){persistTraining();moment.mistakeId=mistake.id}session.review=moment}session.status=`Reviewed ${moves.length} recent ${side(sideToReview)} ${moves.length===1?'move':'moves'}. ${chess.history({verbose:true}).filter(m=>m.color===sideToReview).length>moves.length?'Earlier moves were outside this sample.':''}`;}catch(e){if(e.name!=='AbortError'&&token===engineToken){session.status='Review could not finish: '+e.message}}finally{if(openingPractice===session){if(token===engineToken)engine=null;else session.status='Review interrupted. Tap Finish & review to try again.';session.busy=false;renderBoard();renderPanel()}}}
function startPracticeRecall(){const r=openingPractice?.review;if(!r)return;const original={chess,lastMove,engineResult,free};stopEngine();playing=false;practiceRecall={review:r,original,solved:false,message:''};activeMistakeId=r.mistakeId||null;chess=new Chess(r.move.before);lastMove=null;selected=null;legal=[];renderBoard();renderPanel()}
function attemptPracticeRecall(move){if(practiceRecall.solved){toast('Return to the practice game to continue.');return}try{const m=chess.move(move),best=practiceRecall.review.analysis.moveReview.before[0]?.uci[0];if(m.from+m.to+(m.promotion||'')===best){practiceRecall.solved=true;lastMove=m;checkNotebookMove(m)}else{chess.undo();practiceRecall.message=m.san+' is legal. It differs from the earlier candidate; reveal the explanation to compare, or try again.'}selected=null;legal=[];renderBoard();renderPanel()}catch{}}
function returnOpeningCourse(){const p=openingPractice;if(!p)return;page='teach';history.replaceState(null,'','#teach');renderNav();if(p.deviation)openDeviation(p.deviation.id,p.deviation);else{openStudy(p.courseId,p.returnStep);teachPlanMode=p.returnMode==='plan';renderBoard();renderPanel()}}
document.addEventListener('change',e=>{if(e.target.id==='deviationSelect')openDeviation(e.target.value)});
document.addEventListener('click',e=>{const open=e.target.closest('[data-deviation-open]');if(open){openDeviation(open.dataset.deviationOpen);return}const c=e.target.closest('[data-deviation-choice]');if(c){chooseDeviation(Number(c.dataset.deviationChoice));return}if(e.target.closest('[data-deviation-next]'))stepDeviation(1);if(e.target.closest('[data-deviation-prev]'))stepDeviation(-1);if(e.target.closest('[data-deviation-retry]'))retryDeviation();if(e.target.closest('[data-deviation-return]')&&deviationState){const d=currentDeviation(),at=deviationState.courseStep;openStudy(d.courseId,at)}if(e.target.closest('[data-opening-practice]'))beginOpeningPractice();if(e.target.closest('[data-practice-review]'))finishOpeningReview();if(e.target.closest('[data-practice-recall]'))startPracticeRecall();if(e.target.closest('[data-practice-course]'))returnOpeningCourse();if(e.target.closest('[data-practice-recall-return]')&&practiceRecall){({chess,lastMove,engineResult,free}=practiceRecall.original);practiceRecall=null;activeMistakeId=null;renderBoard();renderPanel()}});

function nextAutomaticExplanation(){const next=nextLessonMove();if(!next)return null;const theory=getOpeningTheory(lesson?.name);let reason=(lesson?.branchNotes||theory?.notes)?.[step]||'';if(deviationState){const c=deviationBoard(currentDeviation(),deviationState.choice,deviationState.cursor);c.move(next.san);reason=explainMove(c,null).facts.join(' ')}if(!reason){const probe=new Chess(chess.fen());probe.move(next.san);reason=explainMove(probe,null).facts.join(' ')}return {san:next.san,reason,text:buildNarration({lead:`${side(chess.turn())} to move. The next taught move is ${next.san}.`,reason,theory:theory?.structure,whitePlan:planText(chess,'w',lesson),blackPlan:planText(chess,'b',lesson)},narrationScope)}}
function speakNextAutomatically(){const next=nextAutomaticExplanation();if(autoExplanationGate.accept({enabled:autoExplain,blocked:autoExplainPaused||drill||playing||document.hidden,fen:chess.fen(),san:next?.san,text:next?.text})){narrator.read(next.text,narrationOptions())}}
document.addEventListener('change',e=>{if(e.target.id!=='autoExplainNext')return;autoExplain=e.target.checked;autoExplainPaused=false;autoExplanationGate.reset();if(autoExplain){showBoardGuidance=true;renderBoardGuidance();speakNextAutomatically();if(!nextLessonMove())$('#narrationStatus').textContent='Auto-explain is on. Open a taught line in Learn mode; it will speak when a next move is available.'}else narrator.stop()});
